/**
 * Chainable Array Utility
 *
 * Provides a fluent interface for chaining array operations.
 * Similar to lodash's chain or underscore's chain.
 *
 * @module utils/LinqArray
 *
 * @example
 * ```ts
 * import { linq } from '@tnp/getgo-logics/quiz-builder'
 *
 * // Immutable (default) - each operation creates new LinqArray
 * const result = linq([1, 2, 3, 4, 5, 6])
 *   .where(x => x > 2)           // [3, 4, 5, 6]
 *   .select(x => x * 2)          // [6, 8, 10, 12]
 *   .where(x => x > 8)           // [10, 12]
 *   .sum()                       // 22
 *
 * // Mutable - operations modify internal array
 * const arr = [1, 2, 3, 4, 5]
 * linq(arr, true)
 *   .shuffle()                   // Modifies arr in place
 *   .take(3)                     // Modifies arr in place
 *   .value()                     // Returns arr (same reference)
 * ```
 */
type LinqSortValue = number | string | (number | string)[];
/** Type-preserving operations that mutate their owning LinqArray. */
export interface LinqArrayInPlace<T> {
    /** @example QB.linq([1, 2, 3]).inPlace.where(value => value > 1) */
    where(predicate: (item: T, index: number) => boolean): LinqArray<T>;
    /** @example QB.linq([1, 2, 3]).inPlace.exclude(2) */
    exclude(...values: T[]): LinqArray<T>;
    /** @example QB.linq([1, 3]).inPlace.insertAt(1, 2) */
    insertAt(index: number, item: T): LinqArray<T>;
    /** @example QB.linq([1, 3, 5]).inPlace.insertAt({ 1: 2, 3: 4 }) */
    insertAt(items: Record<number, T>): LinqArray<T>;
    /** @example QB.linq(['a', 'b', 'c']).inPlace.removeAt(1) */
    removeAt(...indexes: number[]): LinqArray<T>;
    /** @example QB.linq([1, 2, 3]).inPlace.take(2) */
    take(count: number): LinqArray<T>;
    /** @example QB.linq([1, 2, 3]).inPlace.skip(1) */
    skip(count: number): LinqArray<T>;
    /** @example QB.linq([1, 2, 3]).inPlace.shuffle() */
    shuffle(): LinqArray<T>;
    /** @example QB.linq([1, 2, 3]).inPlace.flip() */
    flip(): LinqArray<T>;
    /** @example QB.linq([1, null, 2]).inPlace.notNull() */
    notNull(): LinqArray<NonNullable<T>>;
    /** @example QB.linq([1, 1, 2]).inPlace.unique() */
    unique(): LinqArray<T>;
    /** @example QB.linq([3, 1, 2]).inPlace.orderBy(value => value) */
    orderBy(selector: (item: T) => LinqSortValue): LinqArray<T>;
    /** @example QB.linq([3, 1, 2]).inPlace.orderByDesc(value => value) */
    orderByDesc(selector: (item: T) => LinqSortValue): LinqArray<T>;
}
/**
 * Chainable array wrapper class
 * Provides array-like interface with index access, iteration, and built-in Array methods
 */
export default class LinqArray<T> implements Iterable<T> {
    private data;
    private mutable;
    /**
     * Run a type-preserving operation against this LinqArray and its backing array.
     * Regular methods remain immutable.
     * @example values.inPlace.shuffle()
     * @example values.inPlace.unique().inPlace.orderBy(value => value)
     */
    readonly inPlace: LinqArrayInPlace<T>;
    [index: number]: T;
    constructor(data: T[], mutable?: boolean);
    private replaceData;
    get length(): number;
    /** @example [...QB.linq([1, 2, 3])] */
    [Symbol.iterator](): Iterator<T>;
    /** @example QB.linq([1, 2, 3]).forEach((value, index) => console.log(index, value)) */
    forEach(callbackfn: (value: T, index: number, array: T[]) => void): void;
    /** @example QB.linq([1, 2, 3]).map((value, index) => value + index) */
    map<U>(callbackfn: (value: T, index: number, array: T[]) => U): U[];
    /** @example QB.linq([1, 2, 3]).filter((value, index) => value > index) */
    filter(predicate: (value: T, index: number, array: T[]) => boolean): T[];
    /** @example QB.linq([1, 2, 3]).some(value => value > 2) */
    some(predicate: (value: T, index: number, array: T[]) => boolean): boolean;
    /** @example QB.linq([1, 2, 3]).every(value => value > 0) */
    every(predicate: (value: T, index: number, array: T[]) => boolean): boolean;
    /** @example QB.linq([1, 2, 3]).find(value => value > 1) */
    find(predicate: (value: T, index: number, array: T[]) => boolean): T | undefined;
    /** @example QB.linq([1, 2, 3]).findIndex(value => value === 2) */
    findIndex(predicate: (value: T, index: number, array: T[]) => boolean): number;
    /** @example QB.linq([1, 2, 3]).includes(2, 0) */
    includes(searchElement: T, fromIndex?: number): boolean;
    /** @example QB.linq([1, 2, 3]).indexOf(2, 0) */
    indexOf(searchElement: T, fromIndex?: number): number;
    /** @example QB.linq([1, 2, 3, 4]).slice(1, 3) */
    slice(start?: number, end?: number): T[];
    /** @example QB.linq([1, 2, 3]).reduce((sum, value) => sum + value, 0) */
    reduce<U>(callbackfn: (previousValue: U, currentValue: T, currentIndex: number, array: T[]) => U, initialValue: U): U;
    /** @example QB.linq([1, 2, 3]).join(', ') */
    join(separator?: string): string;
    /**
     * Filter array (alias for filter) - returns LinqArray for chaining
     * @example linq([1,2,3,4]).where(x => x > 2) // LinqArray [3, 4]
     */
    where(predicate: (item: T, index: number) => boolean): LinqArray<T>;
    /**
     * Exclude one or more specific values from the array.
     * @example linq([1,2,3,4]).exclude(2, 4) // LinqArray [1, 3]
     */
    exclude(...values: T[]): LinqArray<T>;
    /**
     * Insert one or more items at zero-based indexes and return a new LinqArray.
     * Use an index equal to the current length to append an item. Bulk indexes
     * describe positions in the resulting array and are applied in ascending order.
     */
    /** @example QB.linq([1, 3]).insertAt(1, 2) // LinqArray [1, 2, 3] */
    insertAt(index: number, item: T): LinqArray<T>;
    /** @example QB.linq([1, 3, 5]).insertAt({ 1: 2, 3: 4 }) // LinqArray [1, 2, 3, 4, 5] */
    insertAt(items: Record<number, T>): LinqArray<T>;
    /**
     * Remove items at one or more zero-based indexes and return a new LinqArray.
     * Indexes are deduplicated and removed from highest to lowest so removals do
     * not shift the positions of items still waiting to be removed.
     * @example linq(['a', 'b', 'c', 'd']).removeAt(1, 3) // LinqArray ['a', 'c']
     * @example values.inPlace.removeAt(0, 2)
     */
    removeAt(...indexes: number[]): LinqArray<T>;
    /**
     * Map array (alias for map) - returns LinqArray for chaining
     * @example linq([1,2,3]).select(x => x * 2) // LinqArray [2, 4, 6]
     */
    select<U>(mapper: (item: T, index: number) => U): LinqArray<U>;
    /**
     * Take first n elements (positive) or last n elements (negative)
     * @example linq([1,2,3,4,5]).take(3) // LinqArray [1, 2, 3]
     * @example linq([1,2,3,4,5]).take(-2) // LinqArray [4, 5]
     */
    take(count: number): LinqArray<T>;
    /**
     * Skip first n elements (positive) or last n elements (negative)
     * @example linq([1,2,3,4,5]).skip(2) // LinqArray [3, 4, 5]
     * @example linq([1,2,3,4,5]).skip(-2) // LinqArray [1, 2, 3]
     */
    skip(count: number): LinqArray<T>;
    /**
     * Shuffle array
     * @example linq([1,2,3,4]).shuffle()
     */
    shuffle(): LinqArray<T>;
    /**
     * Reverse array order (alias: flip)
     * @example linq([1,2,3,4]).flip() // LinqArray [4, 3, 2, 1]
     */
    flip(): LinqArray<T>;
    /**
     * Filter out null and undefined
     * @example linq([1, null, 2, undefined]).notNull() // LinqArray [1, 2]
     */
    notNull(): LinqArray<NonNullable<T>>;
    /**
     * Get unique values
     * @example linq([1,2,2,3,3,3]).unique() // LinqArray [1, 2, 3]
     */
    unique(): LinqArray<T>;
    /**
     * Sort array by selector function (ascending)
     * @example linq([3,1,2]).orderBy(x => x) // LinqArray [1, 2, 3]
     * @example linq([{age:30},{age:20}]).orderBy(x => x.age) // LinqArray [{age:20}, {age:30}]
     * @example linq([{a:1,b:2},{a:1,b:1}]).orderBy(x => [x.a, x.b]) // Sort by a, then b
     */
    orderBy(selector: (item: T) => LinqSortValue): LinqArray<T>;
    /**
     * Sort array by selector function (descending)
     * @example linq([1,2,3]).orderByDesc(x => x) // LinqArray [3, 2, 1]
     */
    orderByDesc(selector: (item: T) => LinqSortValue): LinqArray<T>;
    /**
     * Flatten array one level
     * @example linq([[1,2],[3,4]]).flatten() // LinqArray [1, 2, 3, 4]
     */
    flatten<U>(this: LinqArray<U[]>): LinqArray<U>;
    /**
     * Group items into a chainable array while preserving first-seen key order.
     * @example linq([{type:'a',val:1},{type:'b',val:2},{type:'a',val:3}])
     *   .groupBy(x => x.type)
     *   // LinqArray [{ key: 'a', values: [...] }, { key: 'b', values: [...] }]
     */
    groupBy<K extends string | number>(keySelector: (item: T) => K): LinqArray<{
        key: K;
        values: T[];
    }>;
    /**
     * Execute function for each element (chainable forEach)
     * @example linq([1,2,3]).each(x => console.log(x)).select(x => x * 2)
     */
    each(fn: (item: T, index: number) => void): LinqArray<T>;
    /**
     * Get the wrapped array value as plain Array
     * @example linq([1,2,3]).select(x => x * 2).value() // [2, 4, 6]
     */
    value(): T[];
    /**
     * Alias for value()
     * @example QB.linq([1, 2, 3]).toArray()
     */
    toArray(): T[];
    /**
     * Sum numeric array or extract numbers and sum them
     * @example linq([1,2,3,4]).sum() // 10
     * @example linq([{val:1},{val:2}]).sum(x => x.val) // 3
     */
    sum(selector?: (item: T) => number): number;
    /**
     * Get maximum value or extract and compare
     * @example linq([1,5,3,2]).max() // 5
     */
    max(selector?: (item: T) => number): number | undefined;
    /**
     * Get minimum value or extract and compare
     * @example linq([1,5,3,2]).min() // 1
     */
    min(selector?: (item: T) => number): number | undefined;
    /**
     * Get average value or extract and average
     * @example linq([1,2,3,4]).avg() // 2.5
     */
    avg(selector?: (item: T) => number): number | undefined;
    /**
     * Get first element or first element matching condition
     * @example linq([1,2,3]).first() // 1
     * @example linq([1,2,3,4]).first(x => x > 2) // 3
     */
    first(condition?: (item: T) => boolean): T | undefined;
    /**
     * Get last element or last element matching condition
     * @example linq([1,2,3]).last() // 3
     */
    last(condition?: (item: T) => boolean): T | undefined;
    /**
     * Get random element
     * @example linq([1,2,3]).random() // 2 (random)
     */
    random(): T | undefined;
    /**
     * Get count of elements or count of elements matching condition
     * @example linq([1,2,3]).count() // 3
     */
    count(condition?: (item: T) => boolean): number;
    /**
     * Check if any element matches predicate
     * @example linq([1,2,3]).any(x => x > 2) // true
     */
    any(predicate: (item: T) => boolean): boolean;
    /**
     * Check if all elements match predicate
     * @example linq([1,2,3]).all(x => x > 0) // true
     */
    all(predicate: (item: T) => boolean): boolean;
    /**
     * Check if array contains element
     * @example linq([1,2,3]).contains(2) // true
     */
    contains(item: T): boolean;
    /**
     * Convert array to a plain object using key and value selectors.
     * @example QB.linq(['a', 'b']).toObject((value, index) => index, value => value.toUpperCase())
     */
    toObject<K extends string | number, V>(keySelector: (item: T, index: number) => K, valueSelector: (item: T, index: number) => V): Record<K, V>;
    /** @example QB.linq([{ id: 'a' }, { id: 'b' }]).toObject(item => item.id) */
    toObject<K extends string | number>(keySelector: (item: T, index: number) => K): Record<K, T>;
    /**
     * Alias for toObject
     * @example QB.linq(['a', 'b']).toRecord((value, index) => index, value => value.toUpperCase())
     */
    toRecord<K extends string | number, V>(keySelector: (item: T, index: number) => K, valueSelector: (item: T, index: number) => V): Record<K, V>;
    /** @example QB.linq([{ id: 'a' }, { id: 'b' }]).toRecord(item => item.id) */
    toRecord<K extends string | number>(keySelector: (item: T, index: number) => K): Record<K, T>;
}
