type DateValue = Date | LinqDate;
/**
 * Immutable helpers for working with a Date.
 *
 * Every operation returns a new LinqDate and leaves the original value unchanged.
 */
export default class LinqDate {
    private readonly date;
    constructor(value: Date);
    /** @example QB.linq(new Date('2026-01-15')).addYears(1) */
    addYears(amount: number): LinqDate;
    /** @example QB.linq(new Date('2026-01-31')).addMonths(1) */
    addMonths(amount: number): LinqDate;
    /** @example QB.linq(new Date('2026-01-15')).addDays(7) */
    addDays(amount: number): LinqDate;
    /** @example QB.linq(new Date()).addHours(2) */
    addHours(amount: number): LinqDate;
    /** @example QB.linq(new Date()).addMinutes(30) */
    addMinutes(amount: number): LinqDate;
    /** @example QB.linq(new Date()).addSeconds(45) */
    addSeconds(amount: number): LinqDate;
    /** @example QB.linq(new Date()).addMilliseconds(500) */
    addMilliseconds(amount: number): LinqDate;
    /** @example QB.linq(new Date('2026-01-01')).isBefore(new Date('2026-02-01')) */
    isBefore(value: DateValue): boolean;
    /** @example QB.linq(new Date('2026-02-01')).isAfter(new Date('2026-01-01')) */
    isAfter(value: DateValue): boolean;
    /** @example QB.linq(new Date('2026-01-01')).isSame(new Date('2026-01-01')) */
    isSame(value: DateValue): boolean;
    /** @example QB.linq(new Date('2026-01-15')).format('DD-MM-YYYY') // '15-01-2026' */
    format(pattern: string): string;
    /** @example QB.linq(new Date()).toDate() */
    toDate(): Date;
    /** @example QB.linq(new Date()).value() */
    value(): Date;
    /** @example Number(QB.linq(new Date('2026-01-01'))) */
    valueOf(): number;
    /** @example QB.linq(new Date('2026-01-01')).toISOString() */
    toISOString(): string;
    /** @example QB.linq(new Date('2026-01-01')).toString() */
    toString(): string;
    private update;
    private static daysInMonth;
}
export {};

import LinqArray from './LinqArray.js';
import LinqDate from './LinqDate.js';
/** @example QB.linq(new Date('2026-01-15')).addDays(2).format('DD-MM-YYYY') */
export declare function linq(value: Date): LinqDate;
/** @example QB.linq(3).toArray() // [undefined, undefined, undefined] */
export declare function linq(length: number): LinqArray<undefined>;
/** @example QB.linq(4, index => index + 1).toArray() // [1, 2, 3, 4] */
export declare function linq<T>(length: number, valueFactory: (index: number) => T): LinqArray<T>;
/** @example QB.linq(3, 'x').toArray() // ['x', 'x', 'x'] */
export declare function linq<T>(length: number, defaultValue: T): LinqArray<T>;
/** @example QB.linq([1, 2, 3], true).inPlace.shuffle().toArray() */
export declare function linq<T>(value: T[], mutable?: boolean): LinqArray<T>;
/** @example QB.linq(new Map([['a', 1]]).values()).toArray() */
export declare function linq<T>(value: MapIterator<T>, mutable?: boolean): LinqArray<T>;
/** @example QB.linq({ apples: 2, pears: 3 }).toArray() // [{ key: 'apples', value: 2 }, ...] */
export declare function linq<K extends string, V>(value: Record<K, V>): LinqArray<{
    key: K;
    value: V;
}>;
export { LinqArray, LinqDate };

/**
 * Base class for locale-specific helpers
 * Provides common string transformation utilities
 */
export declare class LocaleHelper {
    /** @example QB.en.toPascal('hello world') // 'HelloWorld' */
    toPascal(str: string): string;
    /** @example QB.en.capitalize('circle') // 'Circle' */
    capitalize(str: string): string;
    /** @example QB.en.toLowerCase('HELLO') // 'hello' */
    toLowerCase(str: string): string;
    /** @example QB.en.toUpperCase('hello') // 'HELLO' */
    toUpperCase(str: string): string;
    /** @example QB.en.toCamelCase('hello world') // 'helloWorld' */
    toCamelCase(str: string): string;
    /** @example QB.en.toKebabCase('hello world') // 'hello-world' */
    toKebabCase(str: string): string;
    /** @example QB.en.toSnakeCase('hello world') // 'hello_world' */
    toSnakeCase(str: string): string;
}

import { LocaleHelper } from './LocaleHelper.js';
export interface VietnameseListOptions<T> {
    /** Formats each item before it is joined. */
    format?: (item: T, index: number) => unknown;
    /** Shared unit appended to every formatted item. */
    unit?: string;
    /** Word placed before the final item. Defaults to "và". */
    conjunction?: string;
    /**
     * Separator between items. Without `conjunction`, it joins every item.
     * With `conjunction`, it joins all items except the final pair.
     */
    separator?: string;
}
export type VietnamesePersonGender = "girl" | "boy" | "female" | "male";
export interface VietnameseValueOptions {
    /** Capitalize the first character of the returned value(s). */
    capitalize?: boolean;
}
export interface VietnameseCalendarNameOptions extends VietnameseValueOptions {
    /** Accepted for API parity; Vietnamese calendar names do not inflect for plurality. */
    plural?: boolean;
}
export type VietnameseDayOfWeekNameStyle = 'full' | 'short';
export interface VietnameseDayOfWeekOptions extends VietnameseValueOptions {
    /** Full name by default; short returns CN, T2, T3, ... */
    style?: VietnameseDayOfWeekNameStyle;
}
export type VietnameseAnimalCategory = "house" | "pet" | "farm" | "wild" | "sea" | "insect";
export interface VietnamesePerson {
    name: string;
    gender: "girl" | "boy";
    subject: "bạn ấy";
    object: "bạn ấy";
    possessiveAdjective: "của bạn ấy";
    possessivePronoun: "của bạn ấy";
    reflexive: "bản thân";
    subjectCapitalized: "Bạn ấy";
    objectCapitalized: "Bạn ấy";
    possessiveAdjectiveCapitalized: "Của bạn ấy";
    possessivePronounCapitalized: "Của bạn ấy";
    reflexiveCapitalized: "Bản thân";
}
export declare class VietnameseHelper extends LocaleHelper {
    private static readonly NAMES_BOY;
    private static readonly NAMES_GIRL;
    private static readonly COLORS;
    private static readonly WEEKDAYS;
    private static readonly WEEKDAYS_SHORT;
    private static readonly MONTHS;
    private static readonly ANIMALS_PET;
    private static readonly ANIMALS_FARM;
    private static readonly ANIMALS_WILD;
    private static readonly ANIMALS_SEA;
    private static readonly ANIMALS_INSECT;
    private static readonly FOODS_BAKED;
    private static readonly FOODS_PIZZA;
    private static readonly FOODS_FRUIT;
    private static readonly FOODS_SNACK;
    private nameList;
    private colorList;
    private animalList;
    private foodList;
    /** @example QB.vi.name('girl') // 'Lan' */
    name(type?: "girl" | "boy" | "female" | "male"): string;
    /**
     * Create a named person with neutral Vietnamese school-story pronouns.
     * Vietnamese pronouns depend on social context, so this deliberately uses
     * "bạn ấy" rather than inferring a relationship from gender.
     * @example QB.vi.person("girl") // { name: "Lan", subject: "bạn ấy", ... }
     * @example QB.vi.person("boy", "Minh")
     */
    person(type: VietnamesePersonGender, name?: string): VietnamesePerson;
    /**
     * Create multiple people with distinct names and neutral Vietnamese pronouns.
     * @example const [older, younger] = QB.vi.people(2)
     * @example const [lan, hoa] = QB.vi.people(2, "girl")
     */
    people(count: number, type?: VietnamesePersonGender): VietnamesePerson[];
    /** @example QB.vi.names(3, 'boy') // three distinct boy names */
    names(count: number, type?: "girl" | "boy" | "female" | "male"): string[];
    /** @example QB.vi.color({ capitalize: true }) // 'Xanh dương' */
    color(options?: VietnameseValueOptions): string;
    /** @example QB.vi.colors(3, { capitalize: true }) */
    colors(count: number, options?: VietnameseValueOptions): string[];
    /** @example QB.vi.colors(4, ['xanh ngọc', 'vàng kim'], { capitalize: true }) */
    colors(count: number, defaultColors?: string[], options?: VietnameseValueOptions): string[];
    /**
     * Return one weekday name. Index 0 is Sunday; omit it for a random day.
     * @example QB.vi.weekday(1, { capitalize: true, plural: false }) // 'Thứ Hai'
     */
    weekday(index?: number, options?: VietnameseCalendarNameOptions): string;
    /**
     * Convert any integer to a weekday using Sunday as 0. Values wrap by seven,
     * so -1 is Thứ Bảy and 7 is Chủ nhật.
     * @example QB.vi.dayOfWeek(1) // 'Thứ Hai'
     */
    dayOfWeek(index: number): string;
    /** @example QB.vi.dayOfWeek(-1, 'short') // 'T7' */
    dayOfWeek(index: number, style: VietnameseDayOfWeekNameStyle): string;
    /** @example QB.vi.dayOfWeek(8, { style: 'short', capitalize: true }) // 'T2' */
    dayOfWeek(index: number, options: VietnameseDayOfWeekOptions): string;
    /**
     * Return all weekday names in Sunday-first calendar order.
     * @example QB.vi.weekdays({ capitalize: true, plural: false })
     */
    weekdays(options?: VietnameseCalendarNameOptions): string[];
    /**
     * Return one month name. Index 1 is tháng Một; omit it for a random month.
     * @example QB.vi.month(1, { capitalize: true }) // 'Tháng Một'
     */
    month(index?: number, options?: VietnameseValueOptions): string;
    /**
     * Return all month names in January-to-December calendar order.
     * @example QB.vi.months({ capitalize: true })
     */
    months(options?: VietnameseValueOptions): string[];
    /**
     * Format iterable items as a natural-language list.
     * @param items - The items to join
     * @param options - Item formatting and joining options
     * @example QB.vi.list(["a", "b", "c"])          // "a, b và c"
     * @example QB.vi.list(["a", "b"])                // "a và b"
     * @example QB.vi.list(["a"])                     // "a"
     * @example QB.vi.list(["a", "b", "c"], { conjunction: "hoặc" }) // "a, b hoặc c"
     * @example QB.vi.list([1, 2, 3], { separator: "; " }) // "1; 2; 3"
     * @example QB.vi.list([1, 2, 3], { separator: "; ", conjunction: "và" }) // "1; 2 và 3"
     * @example QB.vi.list([1, 2], { format: value => value.toFixed(1), unit: "m" }) // "1.0 m và 2.0 m"
     */
    list<T>(items: Iterable<T>, options?: VietnameseListOptions<T>): string;
    /**
     * @deprecated Pass `{ conjunction }` as the second argument.
     * @example QB.vi.list(['a', 'b'], 'hoặc')
     */
    list<T>(items: Iterable<T>, conjunction?: string): string;
    /**
     * Return a random animal name in Vietnamese
     * @param type - Optional category filter
